 public function run(): void {
  $entries = [
            ['160', 'Забота не должна отменять выбор', 'Единица символизирует личную волю, шестёрка — заботу, ноль — возможность остановиться. Число 160 предлагает заметить, где мы соглашаемся помогать автоматически, не проверяя свои силы. Доброе действие становится честнее, когда в нём есть свобода сказать и «да», и «нет».', 'Участие, которое не разрушает личные границы.', 'Молчаливое накопление обиды за собственные жертвы.', 'Когда я в последний раз соглашался из страха разочаровать?', 'Перед следующей просьбой оцени свои силы и ответь без поспешности.'],
            ['161', 'Вернуться к собственным потребностям', 'Единицы по краям числа 161 обрамляют шестёрку — символ дома и ответственности. Это образ возвращения к себе после заботы о других. Быть внимательным к близким важно, но потребность в отдыхе и личном пространстве не делает человека менее любящим.', 'Умение сочетать участие с восстановлением.', 'Ожидание, что окружающие сами заметят твою усталость.', 'О какой своей потребности я давно молчу?', 'Скажи близкому о конкретной потребности спокойно и прямо.'],
            ['162', 'Не решать за того, кому помогаешь', 'Единица связана с инициативой, шестёрка — с поддержкой, двойка — с отношениями. Число 162 напоминает, что помощь может незаметно стать управлением чужой жизнью. Уважение начинается с вопроса, нужна ли она вообще.', 'Поддержка, сохраняющая самостоятельность другого.', 'Контроль, замаскированный добрыми намерениями.', 'Кому я даю советы раньше, чем узнаю его просьбу?', 'В следующем разговоре спроси, нужна ли помощь или просто внимание.'],
            ['163', 'Забота, которую можно услышать', 'Единица обозначает намерение, шестёрка — участие, тройка — выражение. Число 163 предлагает задуматься, насколько понятен другим наш способ любить. Иногда мы много делаем, но почти не говорим о чувствах; иногда говорим красиво, но не замечаем конкретных нужд.', 'Совпадение слов поддержки и реальных действий.', 'Уверенность, что близкие обязаны угадывать наши намерения.', 'Что я считаю очевидным проявлением любви, хотя ни разу не объяснял?', 'Спроси близкого, какая поддержка сейчас была бы для него полезна.'],
            ['164', 'Дом как опора, а не экзамен', 'Единица символизирует выбор, шестёрка — домашнюю заботу, четвёрка — порядок. Число 164 напоминает: дом не обязан выглядеть идеально, чтобы в нём было безопасно и тепло. Стремление всё организовать иногда отнимает у близких право просто жить.', 'Уют и надёжность без жестоких требований.', 'Контроль бытовых мелочей как способ справляться с тревогой.', 'Какая домашняя привычка важнее мне, чем людям рядом?', 'Обсуди одно бытовое правило и разреши себе более гибкий вариант.'],
            ['165', 'Заботиться и позволять меняться', 'Единица обозначает личное решение, шестёрка — привязанность, пятёрка — перемены. Число 165 напоминает, что любить человека — не значит сохранять его прежним. Иногда забота проявляется в способности выдержать чужой рост, даже если привычные роли меняются.', 'Поддержка самостоятельного развития близких.', 'Попытка удержать отношения неизменными через чувство долга.', 'Чьи изменения я воспринимаю как личное отвержение?', 'Спроси близкого, что для него сейчас важно, не сравнивая с прошлым.'],
            ['166', 'Не становиться незаменимым ценой себя', 'Единица символизирует волю, две шестёрки усиливают тему ответственности и близости. Число 166 предлагает проверить, не стала ли роль спасателя единственным способом чувствовать свою ценность. Когда всё держится на одном человеке, страдают и он, и окружающие.', 'Забота, которая учит сотрудничать.', 'Гордость собственной перегруженностью и страх делегировать.', 'Какая обязанность остаётся моей только потому, что я никому её не доверяю?', 'Передай одну посильную задачу другому человеку и не контролируй каждый шаг.'],
            ['167', 'Слушать боль без объяснения', 'Единица символизирует намерение, шестёрка — сострадание, семёрка — поиск смысла. Число 167 напоминает, что стремление понять чужие страдания может превратиться в навязывание объяснений. Иногда человеку нужна не теория, а признание того, что ему тяжело.', 'Присутствие и уважение к чужому переживанию.', 'Обесценивание боли готовыми духовными ответами.', 'Когда я в последний раз объяснял чью-то боль вместо того, чтобы слушать?', 'Выслушай человека, не предлагая смысл или решение без просьбы.'],
            ['168', 'Деньги не заменяют близость', 'Единица связана с выбором, шестёрка — с заботой, восьмёрка — с материальными ресурсами. Число 168 предлагает различать обеспечение и присутствие. Финансовая помощь важна, но она не всегда отвечает на потребность в разговоре, уважении или времени вместе.', 'Ответственное обеспечение, соединённое с человеческим вниманием.', 'Попытка компенсировать эмоциональную дистанцию подарками.', 'Чего близкие просят у меня помимо материальной поддержки?', 'Выдели время для разговора без телефона и параллельных дел.'],
            ['169', 'Отпустить роль вечного помощника', 'Единица символизирует личную позицию, шестёрка — заботу, девятка — завершение. Число 169 напоминает, что иногда пора закончить способ отношений, в котором один всё время спасает, а другой не получает возможности действовать сам.', 'Умение завершать изматывающие сценарии без жестокости.', 'Страх стать ненужным, если перестать решать чужие проблемы.', 'Кем я буду в отношениях, если перестану быть спасателем?', 'Определи одну форму помощи, которую больше не готов выполнять автоматически.'],
            ['170', 'Смелость остаться без ответа', 'Единица символизирует выбор, семёрка — исследование, ноль — пространство неизвестного. Число 170 напоминает: не каждый важный вопрос требует немедленного объяснения. Иногда честное «не знаю» открывает больше возможностей, чем уверенная, но поспешная версия.', 'Любознательность без притворной всезнающести.', 'Поиск красивого ответа только ради облегчения тревоги.', 'Какой вопрос я пытаюсь закрыть раньше, чем действительно разобрался?', 'Запиши его и перечисли, что знаешь точно, а что пока предполагаешь.'],
            ['171', 'Возвращаться к опыту, а не к догме', 'Единицы по краям числа 171 окружают семёрку — символ внутреннего поиска. Это образ человека, который после чтения и размышлений возвращается к собственной жизни. Любая теория полезна лишь настолько, насколько помогает внимательнее видеть реальность.', 'Проверка убеждений личным наблюдением.', 'Защита любимого учения от неудобных фактов.', 'Какое убеждение я повторяю, не проверяя его в повседневности?', 'В течение дня замечай один случай, который не укладывается в привычную теорию.'],
            ['172', 'Не анализировать близость вместо близости', 'Единица символизирует личную позицию, семёрка — размышление, двойка — отношения. Число 172 напоминает, как легко заменить живой разговор объяснением чужих мотивов. Иногда самый глубокий вопрос звучит просто: «Что ты чувствуешь?»', 'Умение быть любопытным к другому без ярлыков.', 'Холодный анализ вместо участия.', 'Какую эмоцию близкого я пытаюсь объяснить, не выслушав?', 'Задай один открытый вопрос и удержись от интерпретации ответа.'],
            ['173', 'Делиться поиском, а не истиной', 'Единица символизирует личное начало, семёрка — внутреннее исследование, тройка — речь. Число 173 предлагает говорить о духовном опыте как о собственном пути, а не готовом законе для всех. Искреннее свидетельство оставляет слушателю свободу.', 'Ясное выражение без претензии на непогрешимость.', 'Использование личных переживаний как доказательства универсальных правил.', 'Где я говорю «так устроен мир», хотя точнее было бы «я это пережил»?', 'Переформулируй одну сильную мысль от первого лица.'],
            ['174', 'Тишина, которой есть место в расписании', 'Единица обозначает намерение, семёрка — созерцание, четвёрка — практическую форму. Число 174 напоминает: внутреннее исследование не обязательно требует особых условий. Иногда короткая регулярная пауза даёт больше ясности, чем редкая многочасовая практика.', 'Небольшая устойчивая привычка внимательности.', 'Превращение тишины в ещё один норматив продуктивности.', 'Какой короткий момент дня я мог бы проживать внимательнее?', 'Проведи три минуты без экрана, просто наблюдая дыхание и звуки.'],
            ['175', 'Не искать бесконечно новую практику', 'Единица связана с выбором, семёрка — поиском, пятёрка — переменами. Число 175 напоминает, что смена подходов может быть исследованием, а может — способом избежать терпеливой работы. Новизна не гарантирует глубины.', 'Готовность исследовать без зависимости от необычного.', 'Погоня за очередным методом вместо применения уже известного.', 'Что я уже понял, но откладываю проверить действием?', 'Выбери одну знакомую практику и повтори её без поиска альтернатив.'],
            ['176', 'Мудрость проявляется в отношении к людям', 'Единица символизирует личный выбор, семёрка — понимание, шестёрка — заботу. Число 176 напоминает: сложные рассуждения о сострадании мало значат, если рядом с нами человек, которого мы не замечаем. Понимание проверяется не только словами.', 'Внимание к людям без демонстрации духовной зрелости.', 'Гордость знаниями при невнимательности к близким.', 'Кому рядом со мной нужна простая человеческая поддержка?', 'Сделай одно доброе действие, не рассказывая о нём публично.'],
            ['177', 'Интуиция без непогрешимости', 'Единица обозначает личный выбор, две семёрки усиливают символику интуиции и поиска. Число 177 предлагает уважать внутренние ощущения, но не путать их с проверенными фактами. Чувство может быть важной подсказкой о тебе самом, не становясь доказательством чужих намерений.', 'Внутренняя чуткость, соединённая с проверкой реальности.', 'Уверенность, что сильное ощущение всегда означает истину.', 'Какой вывод я сделал лишь потому, что он показался мне очевидным?', 'Раздели запись на ощущения, наблюдаемые факты и предположения.'],
            ['178', 'Не продавать смысл ради успеха', 'Единица символизирует намерение, семёрка — поиск смысла, восьмёрка — ресурсы и влияние. Число 178 напоминает, что даже важное дело может измениться под давлением показателей. Доход и охват полезны, если не заставляют обещать людям то, чего невозможно гарантировать.', 'Честное сочетание ценностей и устойчивого дела.', 'Манипуляция надеждой ради признания или прибыли.', 'Какое обещание я не должен давать даже ради большого результата?', 'Проверь одно своё предложение или объявление на завышенные ожидания.'],
            ['179', 'Завершить вопрос, не получив окончательного ответа', 'Единица связана с личной позицией, семёрка — поиском, девятка — завершением. Число 179 напоминает, что иногда мы прекращаем исследование не потому, что всё поняли, а потому, что пора жить дальше. Неопределённость может остаться частью зрелого решения.', 'Способность действовать без абсолютной уверенности.', 'Бесконечный анализ, скрывающий страх ответственности.', 'Какой вопрос удерживает меня от уже доступного шага?', 'Назови решение, которое можно принять с нынешним объёмом знаний.'],
            ['180', 'Ресурсы как пространство выбора', 'Единица символизирует волю, восьмёрка — ресурсы, ноль — открытые возможности. Число 180 предлагает взглянуть на деньги и влияние не как на доказательство человеческой ценности, а как на инструменты. Их смысл определяется тем, что они позволяют поддержать.', 'Ответственное использование возможностей.', 'Накопление без понимания, ради чего оно нужно.', 'Какую важную ценность должны обслуживать мои ресурсы?', 'Запиши одну конкретную цель, ради которой стоит экономить или зарабатывать.'],
            ['181', 'Вернуться к себе после успеха', 'Единицы по краям числа 181 обрамляют восьмёрку — символ достижений. Это образ возвращения к личным мотивам после внешней победы. Успех может многое изменить, но не отвечает автоматически на вопрос, счастлив ли ты выбранным направлением.', 'Способность оценивать результат собственными мерками.', 'Зависимость самооценки от очередного достижения.', 'Что я почувствовал, когда последнее важное дело закончилось?', 'Опиши успех без цифр, статуса и чужих похвал.'],
            ['182', 'Сила, которая умеет договариваться', 'Единица символизирует инициативу, восьмёрка — влияние, двойка — партнёрство. Число 182 напоминает, что настоящий авторитет не обязательно требует последнего слова. Иногда он проявляется в готовности пересмотреть решение после аргументов другого.', 'Лидерство с уважением к равноправию.', 'Использование ресурсов для подавления несогласия.', 'Когда я воспринимаю чужой вопрос как угрозу?', 'В совместном решении сначала выслушай альтернативный вариант.'],
            ['183', 'Ответственность за убедительные слова', 'Единица обозначает выбор, восьмёрка — влияние, тройка — речь. Число 183 напоминает, что вдохновляющее сообщение может побудить другого потратить время, силы или деньги. Поэтому ясность и честность важнее эффектной подачи.', 'Слова, которые помогают человеку принять самостоятельное решение.', 'Преувеличение пользы ради сильной реакции.', 'Какая моя формулировка создаёт ожидание, которого я не могу гарантировать?', 'Перепиши одно обещание так, чтобы оно оставалось привлекательным, но точным.'],
            ['184', 'Успех, который можно поддерживать', 'Единица символизирует цель, восьмёрка — результат, четвёрка — устойчивую структуру. Число 184 напоминает, что разовый рывок и жизнеспособная система — разные вещи. Иногда разумнее уменьшить скорость, чтобы дело не держалось только на изнурении.', 'Долговременная результативность без выгорания.', 'Постоянный аврал как признак якобы высокой эффективности.', 'Что в моём деле перестанет работать, если я отдохну неделю?', 'Определи один процесс, который стоит упростить или передать другому.'],
            ['185', 'Цена независимости', 'Единица связана с выбором, восьмёрка — ресурсами, пятёрка — свободой. Число 185 предлагает честно оценить, что именно даёт самостоятельность. Иногда высокий доход покупается таким количеством обязательств, что свободы остаётся меньше, чем прежде.', 'Согласование материальных целей с образом жизни.', 'Привычка считать любые новые возможности обязательными.', 'Какой ресурс я хочу получить и каким временем готов за него заплатить?', 'Сравни желаемую цель с её реальной ценой в часах и усилиях.'],
            ['186', 'Не покупать право быть любимым', 'Единица символизирует личный выбор, восьмёрка — ресурсы, шестёрка — заботу. Число 186 напоминает, что материальная поддержка не должна превращаться в скрытый договор о послушании. Любовь не становится крепче от подсчёта того, кто сколько дал.', 'Щедрость с уважением к свободе другого.', 'Ожидание благодарности в форме контроля над чужими решениями.', 'Есть ли у моей помощи условие, о котором я не говорю?', 'Назови свои ожидания честно или отпусти их.'],
            ['187', 'После результата спросить «зачем»', 'Единица символизирует намерение, восьмёрка — достижения, семёрка — внутренний поиск. Число 187 предлагает не спешить с новой целью сразу после победы. Иногда пауза нужна, чтобы понять, какое место результат занимает в жизни, а не только в отчёте.', 'Осмысленное отношение к успеху.', 'Бегство в следующую задачу от ощущения пустоты.', 'Что важного изменилось во мне после последнего достижения?', 'Выдели время, чтобы записать не итоги, а переживания завершённого дела.'],
            ['188', 'Власть без поклонения власти', 'Единица символизирует личную волю, две восьмёрки усиливают тему ресурсов и влияния. Число 188 напоминает, что способность распоряжаться многим не даёт права распоряжаться людьми. Устойчивый авторитет требует прозрачных решений и готовности отвечать за последствия.', 'Ответственное влияние, которое не унижает других.', 'Уверенность, что успех делает любое решение правильным.', 'Где я пользуюсь своим положением вместо честного объяснения?', 'Объясни одно важное решение тем, кого оно затрагивает, и выслушай возражения.'],
            ['189', 'Вовремя закончить гонку', 'Единица обозначает личную цель, восьмёрка — достижения, девятка — завершение. Число 189 напоминает: иногда мы продолжаем бороться за результат, который уже перестал быть нашим желанием. Завершение может оказаться более зрелым решением, чем очередное усилие.', 'Свобода менять критерии успеха.', 'Продолжение изматывающего пути только ради оправдания вложенного.', 'Какая цель держится на страхе признать перемену?', 'Напиши, что потеряешь и что сохранишь, если перестанешь за ней гнаться.'],
            ['190', 'Пауза после завершения', 'Единица символизирует новое намерение, девятка — завершение, ноль — открытое пространство. Число 190 напоминает, что после большого окончания не обязательно сразу начинать следующий этап. Пустое место иногда нужно прожить, а не срочно заполнить.', 'Терпение к переходному периоду.', 'Суета ради избегания грусти или неопределённости.', 'Какую паузу я считаю недопустимой, хотя она мне нужна?', 'Оставь немного свободного времени без задачи стать продуктивнее.'],
            ['191', 'Не строить новую роль из старой боли', 'Единицы по краям числа 191 обрамляют девятку — символ завершения. Это образ человека, который возвращается к выбору после утраты или окончания этапа. Но новая идентичность не обязана быть постоянным ответом прошлому.', 'Возможность начать заново без отрицания пережитого.', 'Решения, принятые только ради доказательства, что прошлое больше не ранит.', 'Что я выбираю сейчас ради себя, а не назло прошлому?', 'Опиши новую цель, не упоминая тех, кому хочешь что-то доказать.'],
            ['192', 'Завершить спор, сохранив уважение', 'Единица символизирует собственную позицию, девятка — завершение, двойка — отношения. Число 192 напоминает, что не всякое несогласие нужно доводить до победы. Иногда достаточно признать границы разговора и сохранить человеческое достоинство.', 'Умение выходить из конфликта без унижения другого.', 'Попытка получить последнее слово любой ценой.', 'Что я надеюсь выиграть, продолжая этот спор?', 'Сформулируй завершение разговора без обвинения и требования согласиться.'],
            ['193', 'Не делать прошлое красивее, чем оно было', 'Единица обозначает личный взгляд, девятка — завершение, тройка — рассказ. Число 193 предлагает заметить, как память превращает сложный опыт в простую историю. Честность не требует ни обесценивать прожитое, ни превращать его в безупречный урок.', 'Умение рассказывать о прошлом без самооправдания.', 'Создание легенды, в которой все события обязательно имели ясный смысл.', 'Какую часть своей истории я обычно пропускаю?', 'Запиши воспоминание с двумя противоположными чувствами, которые тогда испытывал.'],
            ['194', 'Закрыть дело без самонаказания', 'Единица символизирует решение, девятка — завершение, четвёрка — порядок. Число 194 напоминает, что завершать проект нужно не только эмоционально, но и практически: передать дела, закрыть обязательства, сохранить нужное. Но порядок не должен превращаться в бесконечную попытку исправить прошлое.', 'Бережное и ясное завершение обязательств.', 'Перфекционизм, не позволяющий поставить точку.', 'Что действительно осталось сделать, а что я лишь пытаюсь переделать?', 'Составь короткий список необходимых завершающих действий.'],
            ['195', 'Не разрушать мосты ради нового начала', 'Единица символизирует личный выбор, девятка — завершение, пятёрка — перемены. Число 195 напоминает, что уходить можно без войны с прошлым. Сильное желание свободы иногда заставляет объявлять всё прежнее ошибкой, хотя там было и ценное.', 'Перемены с благодарностью и ясными границами.', 'Резкость, которой человек пытается убедить себя в правильности ухода.', 'Что я могу оставить позади без обесценивания?', 'Назови одну вещь, которой благодарен завершённому этапу.'],
            ['196', 'Отпустить обязанность быть всем для всех', 'Единица символизирует личную позицию, девятка — окончание, шестёрка — заботу. Число 196 напоминает, что даже самая привычная роль помощника может завершиться. Это не отменяет любви; иногда это делает отношения честнее и позволяет другим повзрослеть.', 'Забота с ясными границами и доверием к другим.', 'Чувство вины за отказ решать чужие проблемы.', 'Какая просьба давно превышает мои возможности?', 'Спокойно обозначь одно ограничение и предложи реалистичную альтернативу, если она есть.'],
            ['197', 'Не требовать от конца окончательного смысла', 'Единица символизирует личное решение, девятка — завершение, семёрка — поиск. Число 197 напоминает: некоторые события заканчиваются, не оставляя ясного объяснения. Можно уважать опыт и продолжать жить, даже если ответ на вопрос «почему» остаётся открытым.', 'Принятие неизвестного без отказа от размышления.', 'Навязчивый поиск единственного объяснения прошлого.', 'Какой ответ я считаю обязательным условием для движения дальше?', 'Запиши, что известно точно, и отдельно — что, возможно, так и останется неизвестным.'],
            ['198', 'Отделить себя от прежних достижений', 'Единица символизирует личность и выбор, девятка — завершение, восьмёрка — результат. Число 198 предлагает увидеть: когда заканчивается успешный этап, может возникнуть страх потерять самого себя. Но опыт остаётся с человеком, даже если титул или цифры больше не актуальны.', 'Устойчивость самоощущения за пределами статуса.', 'Попытка любой ценой сохранить прежний уровень признания.', 'Кто я, если перестану перечислять свои достижения?', 'Назови три качества, не связанные с результатами и должностями.'],
            ['199', 'Начать заново, не отрицая завершения', 'Единица обозначает новый выбор, две девятки усиливают тему окончания цикла. Число 199 напоминает, что решительное начало иногда требует дважды признать конец: сначала во внешних обстоятельствах, затем внутри себя. Но это не предсказание событий, а повод проверить, что мы продолжаем удерживать.', 'Смелость двигаться дальше с уважением к пережитому.', 'Поспешное объявление себя обновлённым, когда чувства ещё требуют внимания.', 'Что уже закончилось в моей жизни, но я продолжаю поддерживать по привычке?', 'Запиши одну завершённую роль и одно действие, которое больше не нужно совершать.']
  ];
  foreach ($entries as $entry) {
   [$number,$title,$symbolism,$light,$shadow,$question,$practice] = $entry;
   $record = NumberMeaning::query()->where('number',$number)->first();
   if (!$record) { continue; }
   $text = (string) $record->symbolism;
   $generated = str_starts_with($text,'Число '.$number.' можно использовать как повод для самонаблюдения.')
    || str_starts_with($text,'Иногда мы замечаем число в тот момент')
    || str_starts_with($text,'Представь это число не как указание судьбы')
    || str_starts_with($text,'Не нужно верить, что совпадение что-то предсказывает')
    || str_starts_with($text,'У чисел нет обязанности объяснять нашу жизнь')
    || str_starts_with($text,'Смысл здесь рождается не в цифрах')
    || str_starts_with($text,'Попробуй на мгновение оставить поиск тайного послания');
   if (!$generated) { continue; }
   $record->update(['title'=>$title,'symbolism'=>$symbolism,'light_side'=>$light,'shadow_side'=>$shadow,'reflection_question'=>$question,'practice'=>$practice]);
  }
 }
